   RebirthAndStartANewRun: "Yeniden doğ ve yeni bir oyuna başla",
   RebirthAndStartANewRunDesc: "Restitutor <i>artımlı (incremental)</i> bir büyük strateji oyunudur - her oyun, bir sonrakinin daha hızlı ilerlemesine ve daha ileri gitmesine imkân tanıyan kalıcı bonuslar sağlar. Bu sisteme <i>yeniden doğuş</i> denir.<br>Yeniden doğduğumuzda, <i>ilhak edip çekirdek yaptığımız</i> topraklar <icon>Legacy</icon>miras puanlarına dönüştürülür; bunlar gelecek oyunlara aktarılır ve güçlü bonuslar bahşeder.<br>Bir sonraki oyun için farklı bir eyalet seçebiliriz - yeniden doğmak için ekrandaki talimatları izleyin.<br>Yeniden doğuştan sonra eğitim tamamlanmış olacak. Yeni edindiğimiz bilgilerle kendi stratejimizi şekillendirmeye ve kendi yolumuzu çizmeye hazırız - artık tarihin seyrine yön vermek bizim elimizde.",
