   TimedActionAppeaseDesc$1: "İsyancıları yatıştırmak, <i>İsyanı</i> $1 azaltır. Yalnızca toprak şu anda isyan halinde <i>değilken</i> kullanılabilir.",
   TimedActionCrackdownDesc$1$2$3: "İsyancılara sert müdahalede bulunmak, <i>İsyanı</i> $1 olarak sıfırlar, lakin $3 yıl boyunca <i>Huzursuzluğu</i> $2 artırır. Yalnızca toprak şu anda isyan halindeyken kullanılabilir.",
   TimedActionDemandElectionBackingDesc$1: "Seçim desteği talep etmek, yaklaşan konsül seçiminde desteklerini bize taahhüt etmelerini sağlar, böylece eyalet desteğimizi $1 artırır.",
   TimedActionDemandTileDesc: "Büyük bir güç olarak toprak talep etmek, talebimiz kabul edildiği takdirde onları toprağı bize devretmeye mecbur bırakır.",
   TimedActionDemandTributeDesc: "Büyük bir güç olarak haraç talep etmek, talebimiz kabul edildiği takdirde bize tek seferlik altın kazandırır.",
   TimedActionDenounceDesc$1$2$3: "Bir eyaleti kınamak, onların bize karşı tutumunu $1 azaltır ve Prestijimizi $2 artırır (eğer rakibimizlerse $3).",
   TimedActionDeterAggressionDesc$1$2: "Saldırganlığı caydırmak, bu eyaletin başka bir eyalete saldırması halinde savunanın yanında savaşa katılmamızı gerektirir. Caydırıcılık yürürlükteyken Prestijimiz $1 artar (eğer rakibimizlerse $2).",
   TimedActionDissolveTreatyDesc: "Bir antlaşmayı feshetmek, bir eyaletin başka bir eyaletle olan diplomatik antlaşmasını sonlandırır. Ayrıca eyaletin yeni antlaşmalar yapmasını da engeller.",
   TimedActionEvangelizeTileDesc: "Hristiyan olmayan bir toprağı Hristiyanlaştırmak, onu eyaletimizin dinine döndürür.",
   TimedActionFabricateCasusBelliDesc: "Savaş Sebebi uydurmak, onlara karşı bize bir <i>Diplomatik İhtilaf</i> Savaş Sebebi kazandırır.",
   TimedActionForceAttackDesc$1$2: "Şiddetli bir taarruz ile, eğer taarruzumuz püskürtülürse $2 savaş skoru yerine daimi ordumuzun $1 kadarını kaybederiz.",
   TimedActionFortifyBordersDesc$1: "Sınırlarımızı tahkim etmek, savaş gayesi olan topraklara sınırı olan topraklarımızın insan gücünü $1 artırır.",
   TimedActionGuaranteeDefenseDesc$1: "Savunmayı garanti etmek, saldırıya uğradıklarında onların savunma savaşına katılmamızı gerektirir. Garantörlük yürürlükteyken bize karşı tutumları $1 artar.",
   TimedActionHireMercenariesDesc: "Paralı asker tutmak, ordumuzu derhal hedef celp miktarına kadar takviye eder.",
   TimedActionInciteUnrestDesc$1: "Sınır kargaşası kışkırtmak, onların eyaletimize sınırı olan topraklarındaki Huzursuzluğu $1 artırır.",
   TimedActionPlunderWarTileDesc: "Bir savaş toprağını yağmalamak, <i>gereken savaş skorunu</i> düşürür ve toprağın geliştirmelerini tahrip eder.",
   TimedActionPublicEnemyDesc$1: "Bir eyaleti <i>halk düşmanı</i> ilan etmek, onların <i>Prestijini</i> ve <i>Savaş Gücünü</i> $1 azaltır. Diğer tüm eyaletler onlara karşı bir <i>Halk Düşmanı</i> Savaş Sebebi elde eder.",
   TimedActionRequestMilitaryAidDesc$1$2: "Askeri yardım talep etmek, Savaş Gücümüzü $1 artırır ve tabimizin Savaş Gücünü $2 azaltır.",
   TimedActionRevealElectionBackingDesc: "Seçim desteğini ifşa etmek, desteklemeyi taahhüt ettikleri iki adayı öğrenmemizi sağlar.",
   TimedActionSetGovernmentFocusDesc: "Hükümet odağını belirlemek, odaklanılmayan diğer iki alan pahasına, odaklanılan alanın aylık üretimini artırır.",
   TimedActionSubvertGarrisonDesc$1: "Sınır garnizonunu ayartmak, onların eyaletimize sınırı olan topraklarının savunmasını $1 düşürür.",
   TimedActionSummonGovernorDesc$1$2: "Bir tabinin valisini huzura çağırmak, Prestijimizi $1 artırır ve tabimizin Prestijini $2 azaltır.",
