   WeHaveEnacted$1: "$1 yürürlüğe koyduk",
   WeHaventEnacted$1: "$1 yürürlüğe koymadık",
   WeHavePledgedSupportToLessThan2Candidates: "2'den az adaya destek taahhüt ettik",
   SpawnProvinceEffectDesc$1$2: "Yeni bir siyasi teşekkül olan <i>$1</i>, şu topraklar üzerinde kuruluyor: $2",
   TheSuebiSettleGallaecia: "Suebiler Gallaecia'ya Yerleşiyor",
   TheSuebiSettleGallaeciaDesc: "Suebilerin bitmek bilmez göçü nihayete eriyor. Galiçya'nın zümrüt tepelerinde kılıçlarını bir kenara bırakıp sabana sarılıyorlar - Roma toprağına kök salan ilk barbar krallığı işte böyle yeşeriyor.",
   TheEternalCityFalls: "Ebedi Şehir Düşüyor",
   TheEternalCityFallsDesc: "Sekiz yüz koca yıl boyunca hiçbir düşman onun aşılmaz surlarında gedik açamadı. Şimdi Vizigotlar Forum'da zafer ziyafetleri çekiyor - ve cihan, Roma'nın bile kanayabileceğini acı bir tecrübeyle idrak ediyor.",
   AKingdomWithinTheEmpire: "İmparatorluk İçinde Bir Krallık",
   AKingdomWithinTheEmpireDesc: "Bir Roma fermanı ile Aquitania toprakları Vizigotlara bahşediliyor. Barbarlar artık Roma toprağını bizzat Roma kanunuyla ellerinde tutuyorlar - bugünün cüzi pazarlığı, yarının müstakil krallığı olacaktır.",
   TheVandalsCrossToAfrica: "Vandallar Africa'ya Geçiyor",
   TheVandalsCrossToAfricaDesc: "Gaiseric, halkına boğazın öte yakasına değin önderlik ediyor ve imparatorluğun tahıl ambarı ayaklarının altına seriliyor. Afrika asırlar boyu Roma'yı doyurmuştu - şimdi ise onun can düşmanlarını besleyecek.",
   CarthageHasFallenAgain: "Kartaca Bir Kez Daha Düştü",
   CarthageHasFallenAgainDesc: "Kartaca tek bir kılıç dahi çekilmeden düşüyor ve Vandallar onun limanlarına tevarüs ediyor. Roma'nın kadim rakibi yeni efendilerin boyunduruğu altında yeniden doğuyor - ve bu defa, koca bir donanmaya sahipler.",
   TheBurgundiansOfSapaudia: "Sapaudia Burgondları",
   TheBurgundiansOfSapaudiaDesc: "Worms'te kılıçtan geçirilip Roma'nın merhametiyle hayatta kalan Burgondlar, Galya'ya bir kalkan olmaları kastıyla Rhône boylarına yerleştiriliyor. Lakin kalkanların, vakti geldiğinde kılıca dönüşmek gibi bir huyu vardır.",
   TheCourtOfAttila: "Attila'nın Sarayı",
   TheCourtOfAttilaDesc: "Attila artık tek başına hükmediyor ve Tuna ona haraç döküyor. Tanrının Kırbacı, Pannonia'daki ahşap sarayından Roma cihanının her iki yarısını da temaşa ediyor - ve nereye darbe indireceğini seçiyor.",
   TheLongHairedKings: "Uzun Saçlı Krallar",
   TheLongHairedKingsDesc: "Kuzeyin bataklıklarından güneye akın eden uzun saçlı krallar, şehirleri birbiri ardına zapt ediyor. Franklar Roma Galyası'nı sadece yağmalamıyor - onu ellerinde tutmaya ve ona hükmetmeye niyetliler.",
   TheSaxonShoreBreaks: "Sakson Kıyıları Düşüyor",
   TheSaxonShoreBreaksDesc: "Hami sıfatıyla davet edilenler, varis sıfatıyla teşrif ediyorlar. Hengist'in gemileri Kent kıyılarına karaya oturuyor - ve Roma'nın kendi kaderine terk ettiği ada, kendine yeni efendiler buluyor.",
   TheScourgeOfGodIsHalted: "Tanrının Kırbacı Durduruldu",
   TheScourgeOfGodIsHaltedDesc: "Katalon Ovaları'nda Roma ve barbar müttefikleri, Attila'ya karşı omuz omuza duruyor. Hun nihayet geri püskürtüldü - lakin zafer hem Roma hem de Got kanıyla yazıldı.",
   TheAlemanniCrossTheRhine: "Alamanlar Ren'i Geçiyor",
   TheAlemanniCrossTheRhineDesc: "Aetius'un ölümüyle Yukarı Ren'i zapt edecek hiçbir kudret kalmadı. Alamanlar sel gibi Alsace'a akıyor - ve kadim hudut toprakları artık Alamannia'ya biat ediyor.",
   FourteenDaysOfPlunder: "On Dört Günlük Yağma",
   FourteenDaysOfPlunderDesc: "Alarik'in üç gün yağmaladığı yerde Gaiseric on dört gün harcıyor. Vandallar Roma'yı iliğine kadar sömürüyor - ve bir imparatoriçeyi yaka paça Kartaca'ya sürüklüyor.",
   TheKingOfTheOstrogoths: "Ostrogotların Kralı",
   TheKingOfTheOstrogothsDesc: "Theoderic, Konstantinopolis'ten Roma'nın dehası ve atalarının çelik iradesiyle dönüyor. Ostrogotlar onun sancağı altında toplanıyor - gözlerini İtalya'ya dikmiş, diyar diyar göçen bir kavim.",
   AnEmpireEndsInSilence: "Bir İmparatorluk Sükût İçinde Can Veriyor",
   AnEmpireEndsInSilenceDesc: "Çocuk yaştaki bir imparator sessiz sedasız sürgüne yollanıyor ve imparatorluk alametleri doğuya, Konstantinopolis'e doğru yelken açıyor. Batı'da yeni bir imparator ilan edilmiyor - kimse buna lüzum dahi görmüyor.",
   WeShallKeepAnEyeOnThem: "Gözümüz onların üzerinde olacak",
   WeShallAssistRomeToRebuild: "Roma'nın ihyasına yardım edeceğiz",
   WeShallFortifyOurOwnDefense: "Kendi müdafaamızı tahkim edeceğiz",
