   ForbidEnlistment: "Celbi Yasakla",
   SelectAHereticProvinceFirst: "Evvela sapkın bir eyalet seçin",
   FirstCouncilOfNicaeaDesc: "İmparator Konstantinus, Roma cihanının dört bir yanından piskoposları Nicaea'ya (İznik) çağırdı. Arius'un kışkırttığı ihtilafı halledecek ve müşterek bir akidede Baba ile Oğul arasındaki münasebeti tayin edecekler.",
   AffirmTheNiceneCreed: "İznik Akidesini Tasdik Et",
   $1CommencesAndLastsFor$2: "$1 başlar ve $2 sürer"
   FirstCouncilOfConstantinopleDesc: "İmparator Theodosius piskoposları Konstantinopolis'e çağırdı. Bu meclis İznik akidesini yeniden tasdik edecek, Makedonyanizm ihtilafına bir cevap verecek ve Kutsal Ruh'un ilahlığını ilan edecektir.",
   AffirmTheDivinityOfTheHolySpirit: "Kutsal Ruh'un ilahlığını tasdik et",
   CouncilOfEphesusDesc: "Piskoposlar, Nestorius'un öğretilerini yargılamak üzere Ephesos'ta toplandı. Mesele, Meryem'in Theotokos olarak adlandırılıp adlandırılamayacağı ve Mesih'te ilahi ile insani olanın ne suretle birleştiğidir.",
   RecognizeMaryAsTheotokos: "Meryem'i Theotokos olarak tanı",
   CouncilOfChalcedonDesc: "Yüzlerce piskopos, imparatorluk otoritesi altında Khalkedon'da toplandı. Mesih'in birbirine karışmaksızın ve bölünmeksizin iki tabiatta tek bir şahıs olduğunu beyan eden bir formül arayışındalar.",
   AcceptTheChalcedonianDefinition: "Khalkedon Tanımını kabul et",
   SecondCouncilOfConstantinopleDesc: "İmparator Iustinianus, Üç Bölüm'ü telin etmek üzere Konstantinopolis'te bir konsil topladı. Amacı, bir yandan Khalkedon'u müdafaa ederken diğer yandan halen bu mutabakatı reddeden Hristiyanları uzlaştırmaktır.",
   CondemnTheThreeChapters: "Üç Bölüm'ü telin et",
   ThirdCouncilOfConstantinopleDesc: "Piskoposlar, Monotelitizm ihtilafına son vermek için yeniden Konstantinopolis'e döndüler. Müzakereleri, Mesih'in hem ilahi hem de insani bir iradeye sahip olduğunu tasdik edecektir.",
   AffirmTheTwoWillsOfChrist: "Mesih'in iki iradesini tasdik et",
   SecondCouncilOfNicaeaDesc: "İmparatoriçe İrene, mukaddes tasvirler üzerindeki kavgayı nihayete erdirmek için piskoposları Nicaea'ya çağırdı. Konsil, ikonaların ilahi birer mabut olarak tapınılmaksızın hürmet görüp göremeyeceğine karar vermelidir.",
