   NullifyTruce: "Mütarekeyi Feshet",
   TimedActionNullifyTruceDesc: "Bir mütarekeyi feshetmek, aktif mütarekelerimizden birini derhal sona erdirir.",
   RelocateCapital: "Başkenti Taşı",
   TimedActionRelocateCapitalDesc: "Eyalet başkentimizi bu toprağa taşı",
   TileIsNotAtWar: "Toprak savaşta değil",
   RelocatingOurProvincialCapitalHasTheFollowingEffect: "Eyalet başkentimizi taşımanın aşağıdaki tesiri olur:",
   AProvinceTransformed: "Dönüşen Bir Eyalet",
   AProvinceTransformedDesc: "Eyaletimiz artık bir zamanlar elinde tuttuğu toprağın iki katına hükmediyor. Yeni şehirler ve kavimler, nizam için valilik makamına bakıyor; bu büyümeyi kendi menfaatimize en iyi ne suretle çevireceğimize karar vermeliyiz.",
   PlanANewProvincialCapital: "Yeni bir eyalet başkenti planla",
   SecureAlliesInTheSenate: "Senatoda müttefikler temin et",
   EmpowerTheProvincialGovernment: "Eyalet hükümetini yetkilendir",
   SpendAtLeast$1$2: "En az $1 $2 harca",
   GenerateAtLeast$1$2: "En az $1 $2 üret",
   MastersOfTheRhineFrontier: "Ren Hududunun Hakimleri",
   MastersOfTheRhineFrontierDesc: "Germania'daki fetihlerimiz Lugdunensis'i Ren'in ötesine taşıdı ve muazzam yeni bir hududu emniyete aldı. Kumandanlar, senatörler ve vergi tahsildarları artık bu zaferin nasıl hatırlanacağını tayin etmek için rekabet ediyor.",
   RewardTheFrontierCommanders: "Hudut kumandanlarını taltif et",
   SeekInfluenceInTheSenate: "Senatoda nüfuz ara",
   CollectTributeFromGermania: "Germania'dan haraç topla",
   TheSouthernGateway: "Güney Kapısı",
   TheSouthernGatewayDesc: "Narbonensis'te bir limanı emniyete alarak Lugdunensis Akdeniz'e doğrudan erişim kazandı. Tacirler, şehrin ileri gelenleri ve kumandanların her biri bu güney kapısını menfaatimize çevirmek için farklı bir vizyon sunuyor.",
   GrantPrivilegesToTheMerchants: "Tacirlere imtiyazlar bahşet",
   UnifyThePortsCivicInstitutions: "Limanın mülki müesseselerini birleştir",
   BuildArsenalsAlongTheWaterfront: "Rıhtım boyunca tersaneler inşa et",
   TheRoadToBritannia: "Britannia Yolu",
   TheRoadToBritanniaDesc: "Manş kıyılarının emniyete alınmasıyla Britannia artık menzilimize girdi. Gemi ustaları kereste topluyor, kılavuzlar gelgitlerin haritasını çıkarıyor ve lejyonlar emir bekliyor—lakin seferin akıbeti, bu geçişe nasıl hazırlanacağımıza bağlı olacaktır.",
   DrillTheInvasionLegions: "İstila lejyonlarına talim yaptır",
   RallyGaulBehindTheExpedition: "Galya'yı seferin arkasında kenetle",
   StockpileSuppliesForTheCrossing: "Geçiş için erzak stokla",
   ACoastBoundTogether: "Birbirine Kenetlenmiş Bir Sahil",
   ACoastBoundTogetherDesc: "Limanlara, memurlara, elçilere ve ordulara yapılan yıllarca süren yatırımlar, sahil mülklerimizi tek bir denizcilik ağına bağladı. Valileri şimdi dişle tırnakla kazanılan bu nizamın hangi gayeye hizmet etmesi gerektiğini soruyor.",
   OpenTheHarboursToCommerce: "Limanları ticarete aç",
   StandardizeLawAlongTheCoast: "Sahil boyunca kanunları yeknesaklaştır",
   StationFleetsInEveryHarbour: "Her limanda donanmalar konuşlandır",
   TheIntegrationOfAquitania: "Aquitania'nın Entegrasyonu",
   TheIntegrationOfAquitaniaDesc: "Aquitania'nın büyük bir kısmı artık idaremiz altındadır. Tecrübeli memurları, faal atölyeleri ve geniş malikaneleri muazzam mükafatlar vadediyor, lakin bu servetin kullanılabilmesi için evvela bu yeni toprakların Lugdunensis'e entegre edilmesi zaruridir."
   KeepTheAquitanianCivilService: "Aquitania mülki idaresini muhafaza et",
   SupplyTheArmyFromLocalWorkshops: "Orduyu mahalli atölyelerden ikmal et",
   SurveyAndSettleTheCountryside: "Kırsalı tahrir ve iskan et",
   EveryArtMastered: "Her İlimde Ustalaşıldı",
   EveryArtMasteredDesc: "Ziraat ve kanundan mühendislik ve harbe kadar, alimlerimiz ve memurlarımız Roma cihanında mevcut her bir ilimde ustalaştı. Onların birikimli ilmi artık eyaleti nesiller boyu yeniden şekillendirebilir.",
   FoundACapitalOfLearning: "Bir ilim başkenti kur",
   GiveScholarsAVoiceInTheSenate: "Alimlere Senatoda söz hakkı ver",
   DispatchExpertsAcrossTheProvince: "Eyaletin dört bir yanına mütehassıslar yolla",
