   ChangeGovernmentFocus: "Hükümet Odağını Değiştir",
   TutorialChangeGovernmentFocusDesc: "Taarruzi bir savaş her ay <icon>Military</icon> askeri puana mal olur. Savaş ilan etmeden evvel, hükümet odağımızı askeri olarak değiştirmeliyiz - bu işlem, diğer iki hükümet puanı pahasına aylık askeri puanımızı artırır.",
   MadeCoreTileRemainsCoreAfterReconquest: "Bir toprak bir defa çekirdek toprağımız olduğunda, onu kaybetsek dahi çekirdek kalmaya devam edecektir - onu geri zapt ettiğimizde yeniden çekirdek yapmamıza lüzum yoktur.",
