   MastersOfThePassesDesc$1: "Düşman Tepe ve Dağ toprakları $1 daha az Savaş Skoru katkısı sağlar",
   ProductiveInvestment: "Verimli Yatırım",
   ProductiveInvestmentDesc$1: "Her toprak, geliştirildiği her sefer için $1 Toprak Çıktısı kazanır",
   CommercialRenown: "Ticari Şöhret",
   $1PrestigeForEachActiveTrade: "Her aktif ticaret için $1 Prestij",
   TheMilestonesOfRaetia: "Raetia Mil Taşları",
   TheMilestonesOfRaetiaDesc: "Raetia boyunca uzanan mil taşları, Septimius Severus devrindeki yeni onarımları kaydediyor. Alp yolları; Italia ile Tuna arasında memurları, tacirleri ve lejyonları taşıyor ve idaremiz bu masraflı işin nasıl finanse edileceğine karar vermelidir.",
   RebuildTheViaRaetia: "Via Raetia'yı yeniden inşa et",
   MakeTheTownsMaintainTheRoads: "Yolların bakımını kasabalara yükle",
   CaracallaCrossesRaetia: "Caracalla Raetia'yı Geçiyor",
   CaracallaCrossesRaetiaDesc: "Caracalla, Alamannilerle yüzleşmek üzere kuzey Italia'dan gelip eyaletimizden geçerek ilerliyor. Memurları erzak, taze binekler ve rehberler talep ediyor, lakin imparatorun varlığı bize aynı zamanda imparatorluk sarayına arzuhal sunmak için nadir bir fırsat veriyor.",
   ProvisionTheImperialArmy: "İmparatorluk ordusunu donat",
   PetitionForStrongerPassForts: "Daha muhkem geçit hisarları için arzuhal sun",
   SellSuppliesAtWartimePrices: "Erzakları savaş dönemi fiyatlarından sat",
   TheAlamanniBreakTheFrontier: "Alamanniler Hududu Yarıyor",
   TheAlamanniBreakTheFrontierDesc: "Büyük bir Alamanni akını Yukarı Cermen-Raetia hududunu vuruyor. Batı Raetia'daki her hisarı ve yerleşimi muhafaza edecek kadar askerimiz olmadığından, meclisimiz eyalet müdafaasının nerede tutunacağına karar vermemizi talep ediyor.",
   HoldEveryFortOnTheOuterWall: "Dış surdaki her hisarı muhafaza et",
   ScreenTheTownsWithFieldTroops: "Kasabaları sahra birlikleriyle perdele",
   AbandonTheExposedDistricts: "Müdafaasız mıntıkaları terk et",
   TheBrennerPassLiesOpen: "Brenner Geçidi Ardına Kadar Açık"
   TheBrennerPassLiesOpenDesc: "Bir Alamanni ordusu, Roma orduları başka yerlerdeki buhranlarla boğuşurken Brenner Geçidi'ni aşıp kuzey Italia'ya giriyor. İmparator Claudius yetişmeden evvel, tükenmiş garnizonlarımızın bu Alp yolunda onlara kafa tutup tutmayacağına karar vermeliyiz.",
   SealTheBrennerPass: "Brenner Geçidi'ni kapat",
   HarassTheInvadersRetreat: "İstilacıların geri çekilişini taciz et",
   LetTheHostPassIntoItalia: "Bırak ordu Italia'ya geçsin",
   TheAugustiAtAugustaVindelicum: "Augustuslar Augusta Vindelicum'da",
   TheAugustiAtAugustaVindelicumDesc: "Diocletianus, yeni bir Alamanni akınının ardından Raetia'dan karşı taarruza geçiyor ve imparatorluk seyahatnameleri akabinde Maximianus ile Augusta Vindelicum'da buluştuğuna işaret ediyor. Gelişleri, idaremizi iki imparatorluk sarayını ağırlamakla mesul kılıyor.",
   StageAnImperialReception: "Bir imparatorluk kabul merasimi tertip et",
   SupplyScoutsForTheCounterattack: "Karşı taarruz için izciler tedarik et",
   PetitionForFrontierFunds: "Hudut ödenekleri için arzuhal sun",
   RaetiaDivided: "Raetia Bölündü",
   RaetiaDividedDesc: "Bir imparatorluk fermanı bize Raetia'nın kayıtlarını, gelirlerini ve memurlarını taksim etmemizi emrediyor. Augusta Vindelicum Raetia Secunda'yı idare edecek, Curia ise Raetia Prima'ya hükmedecek; bu yeniden teşkilatlanmanın ne denli sadakatle tatbik edileceğine karar vermek ise bize kalıyor.",
   CarryOutTheDivisionFaithfully: "Taksimi sadakatle tatbik et",
   KeepTheBestOfficesAtAugusta: "En iyi makamları Augusta'da muhafaza et",
   SendTroopsAndFundsToCuria: "Curia'ya birlikler ve ödenekler yolla",
   ConstantiusAtTheCampiCannini: "Constantius Campi Cannini'de",
   ConstantiusAtTheCampiCanniniDesc: "Lentienseler mütemadiyen hududu ihlal ederek II. Constantius'u Campi Cannini'ye çekiyor. Arbetio ilerlemeden evvel bizden eyalet birlikleri, rehberler ve erzak talep ederken, mahalli toprak sahipleri himayemiz için yalvarıyor.",
   AttachOurBestTroopsToArbetio: "En iyi birliklerimizi Arbetio'nun emrine ver",
   FortifyTheCampiCannini: "Campi Cannini'yi tahkim et",
   OfferTheLentiensesNewTerms: "Lentienselere yeni şartlar sun",
   ValentiniansFrontierTowers: "Valentinianus'un Hudut Kuleleri",
   ValentiniansFrontierTowersDesc: "Valentinianus'un hududu tahkim etme emri makamımıza ulaştı. Hazine, imparatorluk mühendisleri tarafından teklif edilen her kuleyi ve ambarı inşa edemez; bu sebeple programın Raetia'ya düşen payı için öncelikleri tayin etmeliyiz.",
   RaiseAChainOfBurgi: "Bir burgi zinciri inşa et",
   BuildGranariesBesideTheTowers: "Kulelerin yanına ambarlar inşa et",
   RepairOnlyTheStrongestForts: "Yalnızca en muhkem hisarları onar",
   BautoCallsTheSteppeWarriors: "Bauto Bozkır Savaşçılarını Çağırıyor",
   BautoCallsTheSteppeWarriorsDesc: "Juthungiler Raetia Secunda'nın zengin topraklarını yağmalıyor. Bauto, idaremizden hudut ötesinden çağırdığı Hunlar ve Alanların maaşlarını ödemesini ve onları barındırmasını istiyor; böylece bir tehlikeyi, sadakati sikkelere ve yağmaya dayalı yardımcı birliklerle ikame ediyor.",
   PayBautosHunsAndAlans: "Bauto'nun Hunlarına ve Alanlarına ödeme yap",
   MusterTheRaetianLimitanei: "Raetia limitanei birliklerini topla",
   SendEnvoysToBuyAWithdrawal: "Geri çekilmelerini satın almak için elçiler yolla",
   StilichosWinterInRaetia: "Stilicho'nun Raetia'daki Kışı",
   StilichosWinterInRaetiaDesc: "Raetia'daki Vandal ve Alan akınını bastırdıktan sonra Stilicho, Alarik'in Italia'ya ilerleyişini karşılamak üzere birliklere güneye gitmelerini emrediyor. Müdafaasız kalan eyaletimizi emniyette tutarken bu emre ne ölçüde riayet edeceğimize karar vermeliyiz.",
   ReleaseTheTroopsForItalia: "Birlikleri Italia için serbest bırak",
   KeepTheAlpinePassesManned: "Alp geçitlerindeki garnizonları muhafaza et",
   PetitionToSettleThemAsFederates: "Onları foederati olarak iskan etmek için arzuhal sun",
   BurcoAtTheCampiCannini: "Burco Campi Cannini'de",
   BurcoAtTheCampiCanniniDesc: "Dokuz yüz Alemanni eyaletimizi geçip Italia'ya doğru iniyor, orada Majorianus'un subayı Burco onları Campi Cannini'de imha ediyor. Şimdi idaremizden geçitleri emniyete almamızı ve hayatta kalan esirlerin akıbetini tayin etmemizi talep ediyor.",
   HuntTheSurvivorsThroughTheAlps: "Sağ kalanları Alpler boyunca avla",
   StrengthenTheAlpineWatch: "Alp nöbetçilerini takviye et",
   RecruitTheCapturedWarriors: "Esir alınan savaşçıları saflara kat",
   ARealmBeyondTheNorthernFrontier: "Kuzey Hududunun Ötesinde Bir Diyar"
   ARealmBeyondTheNorthernFrontierDesc: "Sancaklarımız artık Portus'ta ve Raetia'nın kuzey hududunun ötesinde dalgalanıyor. Bir zamanlar Alp geçitleriyle tanımlanan eyaletimiz, şimdi Germania'da bir köprübaşına sahip ve bu umulmadık diyarın neye dönüşeceğine karar vermeliyiz.",
   PressOurClaimsInGermania: "Germania'daki hak iddialarımızda ısrar et",
   SettleAndTaxOurConquests: "Fetihlerimizi iskan et ve vergiye bağla",
   TrainAGovernmentForExpansion: "Genişleme için bir hükümet yetiştir",
   AnAlpineProtectorate: "Bir Alp Himayesi",
   AnAlpineProtectorateDesc: "Raetia büyürken komşu Noricum müdafaasız bir bakiyeye kadar küçüldü. Noricum elçileri otoritemiz altında sığınak arıyor ve doğu geçitlerinin ötesindeki rakiplerden korunma mukabilinde sadakat teklif ediyorlar.",
   ReceiveNoricumAsOurClient: "Noricum'u tabimiz olarak kabul et",
   RaetiaReachesTheMediterranean: "Raetia Akdeniz'e Ulaşıyor",
   RaetiaReachesTheMediterraneanDesc: "Akdeniz'deki iki liman artık idaremize biat ediyor ve karayla çevrili Raetia'ya ilk kez denize açılan bir kapı sunuyor. Tacirleri, sulh hakimleri ve denizcileri yeni sahilimizi ne suretle kullanacağımıza dair haber bekliyor.",
   CollectTheHarborCustoms: "Liman gümrüklerini tahsil et",
