   RaetiaAscendantDesc: "Yirmi çekirdek toprak artık kanunlarımızı tanıyor ve Raetia artık dar bir hudut eyaleti olarak göz ardı edilemez. Meclisimiz, bu genişlemiş diyarın kudretini kalıcı bir otoriteye nasıl tahvil edeceğine karar vermelidir.",
