   TheRoadsOfNoricum: "Noricum Yolları",
   TheRoadsOfNoricumDesc: "Taze mil taşları, Lauriacum, Virunum ve Alp geçitlerini birbirine bağlayan askeri yolları onarmaya yönelik bir imparatorluk programına işaret ediyor. İmparatorluk haritacıları, idaremizin bu işgücü ve ödenekleri ne suretle temin edeceğini soruyor.",
