   RaidsOnTheNoricanFrontier: "Noricum Hududuna Akınlar",
   RaidsOnTheNoricanFrontierDesc: "Raporlar, yukarı Tuna müdafaa hatlarını aşıp Noricum'a yapılan akınlardan Alamanni savaş çetelerini mesul tutuyor. Hudut yerleşimleri bizden birlikler talep ederken, müdafaasız toprak sahipleri barışı satın almamız için bizi sıkıştırıyor.",
