   ExpandTheMilitaryWorkshops: "Askeri atölyeleri tevsi et",
   ConcentrateTheGarrisons: "Garnizonları teksif et",
   NoricanBishopsAtSerdica: "Serdica'daki Noricum Piskoposları",
   NoricanBishopsAtSerdicaDesc: "Noricum'dan gelen piskoposlar, teşkilatlı bir eyalet piskoposluğunun bilinen en eski güvenilir kaydı olan Serdica konsiline iştirak ettiler. Onların bu seyahati, büyüyen kilise ile olan münasebetimizi tayin etmek için bize bir fırsat sunuyor.",
