   KeepChurchAffairsLocal: "Kilise meselelerini mahalli tut",
   TheBurgusAtTheYbbs: "Ybbs'teki Burgus",
   TheBurgusAtTheYbbsDesc: "Bir kitabe, Ybbs nehrinin ağzında Lauriacum'dan gelen yardımcı askerler tarafından inşa edilen yeni bir hudut kulesini kaydediyor. Bu tek burgus'u daha geniş bir müdafaa programının dayanak noktasına dönüştürebiliriz.",
