   RequireLaborFromNearbyTowns: "Civardaki kasabalardan işgücü talep et",
   AlaricWaitsInNoricum: "Alarik Noricum'da Bekliyor",
   AlaricWaitsInNoricumDesc: "Alarik ve Gotları Noricum'da ordugâh kurdular ve terk edilmiş bir sefer için imparatorluk sarayından dört bin libre altın talep ediyorlar. Saray cevap verene dek, orduları erzaklarını kasabalarımızın ve yollarımızın kıyısındaki topraklardan temin ediyor.",
   SupplyTheGothicCamp: "Got ordugâhını ikmal et",
