   SellTheMunicipalOffices: "Belediye makamlarını sat",
   CaracallaOnTheDanube: "Caracalla Tuna'da"
   CaracallaOnTheDanubeDesc: "Caracalla, hudut ötesindeki seferinin ardından Tuna'yı teftiş etmek üzere teşrif etti. İmparatorluk sarayı izlerken Brigetio lejyonu, nehir hisarları ve limes boyunca uzanan kasabaların hepsi idaremizden onarımlar ve imtiyazlar talep ediyor.",
   RepairTheBrigetioDefenses: "Brigetio müdafaalarını onar",
   RecountTheFrontierHouseholds: "Hudut hanelerini yeniden tahrir et",
   PetitionForVeteranSettlers: "Gazi yerleşimciler için arzuhal sun",
   IngenuusAtSirmium: "Ingenuus Sirmium'da",
   IngenuusAtSirmiumDesc: "Bu buhrana dair kafa karıştırıcı kayıtlar, Gallienus Pannonia'dan epey uzaktayken Ingenuus'un Sirmium'da imparator ilan edilişini bu yıllara tarihler. Subayları erzak talep ediyor, sadık kumandanlar eyaletin ötesinde toplanıyor ve kasabalarımız çok yakında başka bir Roma ordusunun kapıya dayanacağından korkuyor.",
   ProvisionTheSirmiumGarrison: "Sirmium garnizonunu donat",
   SecureTheTownsForGallienus: "Kasabaları Gallienus adına emniyete al",
   SealTheProvincialTreasury: "Eyalet hazinesini mühürle",
   TheUnfinishedWorksOfProbus: "Probus'un Yarım Kalan İşleri",
   TheUnfinishedWorksOfProbusDesc: "İmparator Probus, bataklıkları kurutmalarını emrettikten sonra Sirmium yakınlarında bizzat kendi askerleri tarafından katledildi. Yarı kazılmış kanal, sular altında kalmış tarlalar ve sarsılmış garnizon artık idaremizin omuzlarındadır.",
   FinishTheCanalWithPaidLabor: "Kanalı ücretli işgücüyle tamamla",
   PetitionToPunishTheMutineers: "İsyancıların cezalandırılması için arzuhal sun",
   AbandonProbussReclamation: "Probus'un ıslah çalışmasını terk et",
   TheConferenceAtCarnuntum: "Carnuntum Konferansı",
   TheConferenceAtCarnuntumDesc: "Diocletianus, Carnuntum'da Galerius ve Maximianus ile buluşmak üzere inzivadan döndü. Sarayları, eyaletimizden delegeleri ağırlamasını, yolları muhafaza etmesini ve imparatorluğun ihtilaflı verasetini halletmeye matuf bu toplanmayı donatmasını bekliyor.",
   PrepareAnImperialResidence: "Bir imparatorluk ikametgahı hazırla",
   GuardTheRoadsAndDelegates: "Yolları ve delegeleri muhafaza et",
   PetitionForTaxRemissions: "Vergi muafiyetleri için arzuhal sun",
   TheSlaughterAtMursa: "Mursa Katliamı",
   TheSlaughterAtMursaDesc: "II. Constantius ve Magnentius'un orduları Mursa'nın dışında karşı karşıya geldi. Her iki taraf da erzak talep ediyor, tarlalar muharebenin güzergahında yatıyor ve memurlarımız, eyaletin nadiren şahit olduğu ölçekte zayiatlar için hazırlık yapmalıdır.",
