   OpenHospitalsAndGranaries: "Şifahaneleri ve ambarları aç",
   WithholdStoresFromBothArmies: "Erzakları her iki ordudan da esirge",
   TheMurderOfKingGabinius: "Kral Gabinius'un Katli",
   TheMurderOfKingGabiniusDesc: "Bir Roma hudut kumandanı, Quadi kralı Gabinius'u bir ziyafet esnasında katletti. Quadi ve Sarmat savaş çeteleri şimdi Tuna'yı aşıp kuzey mıntıkalarımıza akın ediyor ve müdafaasız kırsal, himaye için gözlerinin içine bakıyor.",
   ShelterTheFarmsBehindWalls: "Çiftlikleri surların ardında himaye et",
   MusterMobileFrontierTroops: "Seyyar hudut birlikleri topla",
   TheRoadsToItalia: "Italia Yolları",
   TheRoadsToItaliaDesc: "Radagaisus ve muazzam bir Got ordusu, imparatorluk takviyeleri başka yerlere sevk edilirken Tuna topraklarından geçip Italia'ya doğru ilerliyor. Mülteciler yollarımıza yığılıyor ve her bir hudut hisarı bizden adam ve tahıl istiyor.",
   HoldTheRemainingDanubeForts: "Geriye kalan Tuna hisarlarını muhafaza et",
   EscortTheRefugeesToSirmium: "Mültecilere Sirmium'a kadar refakat et",
   StripTheAbandonedPosts: "Terk edilen karakolları tahliye edip sök",
   TheHunsDemandOurFrontier: "Hunlar Hududumuzu Talep Ediyor",
   TheHunsDemandOurFrontierDesc: "Ravenna elçileri Hun hükümdarlarıyla pazarlık yaptı ve Hun yüzbaşıları şimdi idaremizden hisarlar, erzak ve rehineler talep ediyor. Yardıma gelecek hiçbir ordu yok, lakin biz boyun eğmedikçe Pannonia hükmetmemiz için bizim kalacaktır.",
   OfferTributeButNoTerritory: "Haraç teklif et lakin toprak verme",
   ReinforceTheFrontierTowns: "Hudut kasabalarını takviye et",
   RecruitHunnicBorderGuards: "Hun hudut muhafızları devşir",
   TheEarthquakeAtSavaria: "Savaria Zelzelesi",
   TheEarthquakeAtSavariaDesc: "Vekayinamelerin 455 yahut 456 yılında kaydettiği şiddetli bir zelzele Savaria'yı vurdu. Amme binaları yıkıldı, aileler açıkta uyuyor ve batı Pannonia'nın yolları, yiyecek ve sığınak arayan kazazedelerle tıkanmış vaziyette.",
   RebuildThePublicBuildings: "Amme binalarını yeniden inşa et"
   HouseSurvivorsOnNearbyEstates: "Kazazedeleri civar malikanelerde iskan et",
   SalvageStoneForTheFrontier: "Taşları hudut için devşir",
   ClaimsOnTheUpperDanube: "Yukarı Tuna Üzerindeki Hak İddiaları",
   ClaimsOnTheUpperDanubeDesc: "Tahkim edilmiş kasabalarımız ve dolu hazinemiz bize Pannonia'nın batı hududunun ötesine bakma imkanı veriyor. Tacirler ve subaylar, şayet resmi hak iddialarını finanse etmeye ve Noricum ile harbe girmeye hazırlıklıysak, Vindobona ve Flavia Solva'nın yukarı Tuna yollarını emniyete alacağını müdafaa ediyor.",
   PressOurNoricanClaims: "Noricum iddialarımızda ısrar et",
   APannonianCoast: "Bir Pannonia Sahili",
   APannonianCoastDesc: "Üç Akdeniz sahil toprağı artık idaremize biat ediyor. Nehir yolları bir zamanlar Pannonia'dan güneye mallar taşırdı; şimdi memurlarımız, elçilerimiz ve askerlerimiz bizzat kendi limanlarımızda duruyor. Bu yeni deniz hududunu hükümetin hangi kolunun şekillendireceğine karar vermeliyiz.",
   AdministerTheCoastalCities: "Sahil şehirlerini idare et",
   OpenTheHarborsToEnvoys: "Limanları elçilere aç",
   MusterTheCoastalGarrisons: "Sahil garnizonlarını topla",
   TheNoricanPetition: "Noricum Arzuhali",
   TheNoricanPetitionDesc: "Noricum bir avuç toprağa kadar küçülürken diyarımız büyüdü. Hanedan evliliği ve müdafaa paktı saraylarımızı halihazırda birbirine bağlıyor ve Noricum elçileri şimdi bu bağların Pannonia idaresinde kalıcı bir himayeye dönüşüp dönüşemeyeceğini soruyor.",
   PannoniaAscendant: "Pannonia Yükseliyor",
   PannoniaAscendantDesc: "Beş zafer ve emniyete alınan on yeni birleşmiş toprak, idaremizin itibarını dönüştürdü. Askerler, senatörler ve eyalet cemiyetlerinin her biri Pannonia'nın yükselişinde paye talep ediyor ve meclisimiz fethi kalıcı bir otoriteye hangi mutabakatın dönüştüreceğine karar vermelidir.",
   ClaimAMandateToGovern: "İdare etmek için bir emirname talep et",
   HonorOurSenatorsAndGenerals: "Senatörlerimizi ve generallerimizi onurlandır",
   WelcomeThePeoplesWeNowGovern: "Artık idare ettiğimiz kavimleri kucakla",
   PannoniaBetweenEastAndWest: "Doğu ile Batı Arasında Pannonia",
   PannoniaBetweenEastAndWestDesc: "Noricum ve Dalmatia bütünüyle diyarımıza bağlandı, bu da Pannonia'ya Alp geçitlerinin ve Adriyatik ardalanının hakimiyetini veriyor. Meclisimiz artık daha büyük bir kudrete giden iki yol görüyor: batıda Raetia ve Italia'ya doğru yahut doğuda Tuna boyunca Moesia ve Dacia'ya doğru.",
   PrepareAWesternCampaign: "Bir batı seferi hazırla",
   PrepareAnEasternCampaign: "Bir doğu seferi hazırla",
