   HaveAtLeast$1TotalTileUpgrades: "Toplamda en az $1 toprak geliştirmesine sahip ol",
   CrossroadsTaxDistricts: "Kavşak Vergi MıntıkaIarı",
   $1LandTaxForEachNeighboringProvinceUpTo$2: "Komşu olan her bir eyalet için $1 Arazi Vergisi (en fazla $2)",
   BountifulFrontiers: "Bereketli Hudutlar",
