   AQuestionOfLegitimacyDesc$1$2$3$4: "$1 ($2 İdari, $3 Diplomatik, $4 Askeri) isminde küçük bir çocuğun sarayda peydah olduğuna dair havadisler bize ulaştı. Çocuğun valimizin kanından olduğu söyleniyor ve doğumu sır perdesi ve skandallarla örtülü olsa da, kimse benzerliği inkar edemiyor.",
   ANewGovernorDesc$1$2$3$4$5$6: "İhtiyar vali bu dünyadan göçtü, lakin hazırlıksız değil. Varisi $1 ($2 İdari, $3 Diplomatik, $4 Askeri, $5 yaşında, $6 evlat), idarenin yükünü omuzlamak üzere öne çıkıyor. Devlet çarkları dönmeye devam ediyor—eskiye nazaran biraz daha yavaş olsa da.",
   TheGovernorDiesWithoutAnHeirAndForAMomentNoOneRulesDesc$1$2$3$4$5$6: "Vali varis bırakmadan vefat etti ve bir anlığına kimse hükmedemedi. Senato, halef olarak $1'i tayin etti ($2 İdari, $3 Diplomatik, $4 Askeri, $5 yaşında, $6 evlat), lakin uzaktan dayatılan otorite tam oturmuyor. Nizam sürüyor, lakin itimat sarsıldı.",
